// Preserve relatedEmergency and citations from the English data
const enSeasonal = en.seasonal;
const seasonalKeys = ['summer-heat', 'winter-paw-care', 'christmas-foods', 'halloween-candy', 'fireworks-anxiety', 'spring-allergies', 'thanksgiving', 'easter-chocolate'];
for (const key of seasonalKeys) {
  if (enSeasonal[key].relatedEmergency) {
    ar[key].relatedEmergency = enSeasonal[key].relatedEmergency;
  }
  if (enSeasonal[key].citations) {
    ar[key].citations = enSeasonal[key].citations;
  }
}

// Write Arabic translations
const arData = JSON.parse(fs.readFileSync('messages/ar.json', 'utf8'));
arData.seasonal = { ...arData.seasonal, ...ar };
fs.writeFileSync('messages/ar.json', JSON.stringify(arData, null, 2));
console.log('ar.json updated with complete Arabic seasonal translations');